 "content": "from collections import deque


def transform(grid):
    """Copy the connected colored motif around one 5 marker to the other 5."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) != 2:
        return out

    # Find orthogonally connected non-background components.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(component)

    # The template marker belongs to the larger component; the other marker is the destination.
    marker_component = None
    for component in components:
        if any(grid[r][c] == 5 for r, c in component) and len(component) > 1:
            marker_component = component
            break
    if marker_component is None:
        return out

    source = next((p for p in markers if p in marker_component), None)
    destination = next((p for p in markers if p != source), None)
    if source is None or destination is None:
        return out

    dr, dc = destination[0] - source[0], destination[1] - source[1]
    out[destination[0]][destination[1]] = 0
    for r, c in marker_component:
        value = grid[r][c]
        if value == 5:
            continue
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = value
    return out
